const config = $("Config").first().json;
const rawItems = $input.all().map(i => i.json);
const firstItem = rawItems[0] || {};
const attachments = Array.isArray(firstItem.attachments) ? firstItem.attachments : rawItems;

function attachmentName(attachment) {
  return String(attachment.name || attachment.fileName || "").trim();
}

const imageAttachments = attachments.filter((attachment) => /\.jpe?g$/i.test(attachmentName(attachment)));
function normalizedMockupBase(attachment) {
  return attachmentName(attachment)
    .toLowerCase()
    .replace(/\.[^.]+$/i, "")
    .replace(/[\s_-]+/g, "");
}
function mockupNumber(attachment) {
  const match = normalizedMockupBase(attachment).match(/^mockup0?([1-4])$/);
  return match ? Number(match[1]) : null;
}

const safeMockups = imageAttachments
  .map((attachment) => ({ attachment, number: mockupNumber(attachment) }))
  .filter((entry) => entry.number !== null)
  .sort((a, b) => a.number - b.number);
const mockup = safeMockups[0]?.attachment || null;

if (!mockup) {
  return [{ json: {
    cardId: config.cardId,
    cardName: config.cardName,
    mockupOk: false,
    mockupError: "Kein kundensicheres Mockup gefunden. Erlaubt sind Mockup1 bis Mockup4 oder Mockup01 bis Mockup04 als JPG/JPEG. Kein image.png, kein PNG/WebP, kein Cover, keine sonstigen Attachments.",
    attachmentNames: attachments.map(attachmentName).filter(Boolean).join(", ")
  } }];
}

const previews = Array.isArray(mockup.previews) ? mockup.previews : [];
const bestPreview = previews
  .filter((preview) => preview && preview.url && preview.width && preview.height)
  .sort((a, b) => (b.width * b.height) - (a.width * a.height))[0];

const fn = mockup.fileName || mockup.name;
const originalUrl = "https://api.trello.com/1/cards/" + config.cardId + "/attachments/" + mockup.id + "/download/" + encodeURIComponent(fn);
const previewUrl = bestPreview && bestPreview.url ? bestPreview.url.replace("https://trello.com/1/", "https://api.trello.com/1/") : "";
const downloadUrl = previewUrl || originalUrl;

return [{ json: {
  cardId: config.cardId,
  cardName: config.cardName,
  mockupOk: true,
  selectedMockupName: attachmentName(mockup),
  selectedMockupAttachmentId: mockup.id,
  selectedMockupFileName: fn,
  selectedMockupMimeType: mockup.mimeType || "",
  selectedMockupNumber: mockupNumber(mockup),
  selectedMockupSource: bestPreview ? "trello_preview_" + bestPreview.width + "x" + bestPreview.height : "original",
  downloadUrl
} }];

const config = $('Config').first().json;
const staticData = $getWorkflowStaticData('global');
const now = new Date();
const dayKey = now.toLocaleDateString('en-CA', { timeZone: 'Europe/Berlin' });
const hourKey = dayKey + 'T' + now.toLocaleTimeString('de-DE', { timeZone: 'Europe/Berlin', hour: '2-digit', hour12: false });
const MAX_GROK_PER_DAY = 80;
const MAX_GROK_PER_HOUR = 20;

if (staticData.grokDayKey !== dayKey) {
  staticData.grokDayKey = dayKey;
  staticData.grokDayCount = 0;
}

if (staticData.grokHourKey !== hourKey) {
  staticData.grokHourKey = hourKey;
  staticData.grokHourCount = 0;
}

if ((staticData.grokDayCount || 0) >= MAX_GROK_PER_DAY) {
  throw new Error('Grok safety cap reached: max ' + MAX_GROK_PER_DAY + ' video starts per day. Card: ' + config.cardId);
}

if ((staticData.grokHourCount || 0) >= MAX_GROK_PER_HOUR) {
  throw new Error('Grok safety cap reached: max ' + MAX_GROK_PER_HOUR + ' video starts per hour. Card: ' + config.cardId);
}

staticData.grokDayCount = (staticData.grokDayCount || 0) + 1;
staticData.grokHourCount = (staticData.grokHourCount || 0) + 1;
staticData.lastGrokStartAt = now.toISOString();
staticData.lastGrokCardId = config.cardId;

const binaryData = $input.first().binary;
if (!binaryData || !binaryData.data) throw new Error('Keine Binary-Daten');

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');
const mimeType = binaryData.data.mimeType || 'image/jpeg';
if (!mimeType.startsWith('image/')) {
  throw new Error('Download fehlgeschlagen: mimeType ist ' + mimeType + ' statt image/*. Trello-Auth Problem?');
}

const dataUri = 'data:' + mimeType + ';base64,' + base64;
const approxBytes = Buffer.byteLength(dataUri, 'utf8');
if (approxBytes > 5 * 1024 * 1024) {
  throw new Error('Grok Data-URI zu groß (' + approxBytes + ' Bytes). Bild vor Video verkleinern oder Upload-Flow verwenden.');
}

const prompt = 'Cinematic product animation based on the provided image. The scene starts dimly lit. The custom neon sign smoothly transitions from off to on, glowing with vibrant, flicker-free light. CRITICAL: Preserve the EXACT color temperature from the source image. If the sign is cool white, keep it cool white. If it is warm white, keep it warm white. Color accuracy is paramount. The illumination casts realistic reflections and a color-accurate ambient glow onto the wall. A slow, subtle camera dolly-in amplifies depth. Maintain hyper-realistic textures of the sign and wall. Professional commercial lighting style, shallow depth of field. The sign shape and text must remain perfectly stable and unchanged throughout. No morphing, no distortion, no warping of the sign. No audio.';

return [{ json: {
  cardId: config.cardId,
  grokBody: {
    model: 'grok-imagine-video',
    prompt,
    image: { url: dataUri },
    duration: 8,
    resolution: '720p'
  }
} }];

const response = $input.first().json;
const config = $('Config').first().json;
const staticData = $getWorkflowStaticData('global');
const errorStatus = Number(response && response.error && response.error.status || response.statusCode || response.status || 0);

if (errorStatus === 429) {
  const now = new Date();
  const cooldownUntil = new Date(Date.now() + 30 * 60 * 1000);
  staticData.grokRateLimitedUntil = cooldownUntil.toISOString();
  staticData.lastGrokRateLimitAt = now.toISOString();
  staticData.lastGrokRateLimitCardId = config.cardId;
  console.log('Grok rate limited (429). Cooldown bis ' + cooldownUntil.toISOString() + '. Card: ' + config.cardId);
  return [{ json: {
    rateLimited: true,
    transient: true,
    reason: 'Grok/xAI Provider Rate Limit 429',
    action: 'Automatischer Retry: Karte bleibt in der KI-Video-Liste. Der Workflow startet neue Grok-Jobs erst wieder nach dem Cooldown.',
    cooldownUntil: cooldownUntil.toISOString(),
    cooldownUntilBerlin: cooldownUntil.toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }),
    cardId: config.cardId,
    cardName: config.cardName,
    trelloCardUrl: config.cardUrl || ('https://trello.com/c/' + config.cardId),
    workflowName: 'KI-Video Generator v1.0',
    observedAt: now.toISOString()
  } }];
}

if (response && response.error) {
  throw new Error('Grok Submit fehlgeschlagen: ' + JSON.stringify(response).substring(0, 500));
}

const requestId = response.request_id || response.id || response.taskId;
if (!requestId) throw new Error('Keine Grok Request ID: ' + JSON.stringify(response).substring(0, 500));

staticData.grokRateLimitedUntil = null;
return [{ json: {
  rateLimited: false,
  requestId,
  cardId: config.cardId,
  attempts: 0
} }];

const status = $input.first().json;
const prev = $('Save Request ID').first().json;
const attempts = (prev.attempts || 0) + 1;
const normalizedStatus = String(status.status || '').toLowerCase();

if (['done', 'completed', 'succeeded'].includes(normalizedStatus)) {
  const videoUrl = (status.video && (status.video.url || status.video.download_url)) ||
    status.video_url || status.url || status.download_url ||
    (status.output && (status.output.url || status.output.video_url || status.output.download_url)) ||
    (status.result && (status.result.url || status.result.video_url || status.result.download_url)) ||
    (Array.isArray(status.outputs) && status.outputs[0] && (status.outputs[0].url || status.outputs[0].video_url)) || '';

  if (!videoUrl) {
    throw new Error('Grok Task fertig, aber ohne Output-URL: ' + JSON.stringify(status).substring(0, 500));
  }

  return [{ json: {
    done: true,
    videoUrl,
    cardId: prev.cardId,
    attempts,
    rawResponse: JSON.stringify(status).substring(0, 2000)
  } }];
}

if (['failed', 'expired', 'canceled', 'cancelled'].includes(normalizedStatus)) {
  throw new Error('Grok Video fehlgeschlagen: ' + JSON.stringify(status).substring(0, 500));
}

if (attempts >= 60) throw new Error('Grok Timeout nach ' + attempts + ' Versuchen');

return [{ json: {
  done: false,
  requestId: prev.requestId,
  cardId: prev.cardId,
  attempts
} }];

const SOURCE_LIST_ID = '69ea22fe1431c2e7d7e7b3c4'; // KI-Video an Kunden schicken
const VIDEO_SENT_LABEL_ID = '69ea8cb44dafe69b2a31350c'; // Video gesendet
const MAX_GROK_PER_DAY = 80;
const MAX_GROK_PER_HOUR = 20;
const LEASE_MS = 20 * 60 * 1000;
const cards = $input.all().map(i => i.json);

function hasLabelId(card, labelId) {
  return (card.idLabels || []).includes(labelId);
}

function cardCreatedAtMs(card) {
  const rawId = String(card && card.id || '');
  if (!/^[0-9a-fA-F]{24}$/.test(rawId)) return Number.MAX_SAFE_INTEGER;
  const seconds = Number.parseInt(rawId.slice(0, 8), 16);
  return Number.isFinite(seconds) ? seconds * 1000 : Number.MAX_SAFE_INTEGER;
}

const staticData = $getWorkflowStaticData('global');
const now = new Date();
const existingLeaseUntilRaw = staticData.kiVideoLeaseUntil || '';
const existingLeaseCardId = staticData.kiVideoLeaseCardId || '';

if (existingLeaseUntilRaw && existingLeaseCardId) {
  const existingLeaseUntil = new Date(existingLeaseUntilRaw);
  if (existingLeaseUntil > now) {
    console.log('[KI VIDEO LEASE] Active lease until ' + existingLeaseUntil.toISOString() + ' for card ' + existingLeaseCardId + '. Skipping new run.');
    return [];
  }

  staticData.kiVideoLeaseUntil = null;
  staticData.kiVideoLeaseCardId = null;
  staticData.kiVideoLeaseCardName = null;
  staticData.kiVideoLeaseAcquiredAt = null;
}

const eligibleCards = cards
  .filter(card =>
    !String(card.name || '').trim().startsWith('FEHLER -') &&
    !hasLabelId(card, VIDEO_SENT_LABEL_ID)
  )
  .sort((a, b) => {
    const createdDiff = cardCreatedAtMs(a) - cardCreatedAtMs(b);
    if (createdDiff !== 0) return createdDiff;
    return String(a.id || '').localeCompare(String(b.id || ''));
  });
const card = eligibleCards[0];
if (!card) return [];

const rateLimitedUntil = staticData.grokRateLimitedUntil ? new Date(staticData.grokRateLimitedUntil) : null;
if (rateLimitedUntil && rateLimitedUntil > now) {
  console.log('[KI VIDEO RATE LIMIT] Grok cooldown active until ' + rateLimitedUntil.toISOString() + '. Keeping card queued: ' + card.id);
  return [];
}
if (rateLimitedUntil && rateLimitedUntil <= now) {
  staticData.grokRateLimitedUntil = null;
}

const dayKey = now.toLocaleDateString('en-CA', { timeZone: 'Europe/Berlin' });
const hourKey = dayKey + 'T' + now.toLocaleTimeString('de-DE', { timeZone: 'Europe/Berlin', hour: '2-digit', hour12: false });

if (staticData.grokDayKey !== dayKey) {
  staticData.grokDayKey = dayKey;
  staticData.grokDayCount = 0;
}

if (staticData.grokHourKey !== hourKey) {
  staticData.grokHourKey = hourKey;
  staticData.grokHourCount = 0;
}

if ((staticData.grokDayCount || 0) >= MAX_GROK_PER_DAY) {
  console.log('[KI VIDEO CAP] daily cap reached. Keeping trigger label on card for later retry: ' + card.id);
  return [];
}

if ((staticData.grokHourCount || 0) >= MAX_GROK_PER_HOUR) {
  console.log('[KI VIDEO CAP] hourly cap reached. Keeping trigger label on card for later retry: ' + card.id);
  return [];
}

const leaseUntil = new Date(now.getTime() + LEASE_MS);
staticData.kiVideoLeaseUntil = leaseUntil.toISOString();
staticData.kiVideoLeaseCardId = card.id;
staticData.kiVideoLeaseCardName = card.name || '';
staticData.kiVideoLeaseAcquiredAt = now.toISOString();

const regenerateOnly = false;
const triggerLabel = { id: '', name: 'column_trigger' };

return [{ json: {
  cardId: card.id,
  cardName: card.name,
  cardUrl: card.shortUrl || ('https://trello.com/c/' + card.id),
  sourceListId: SOURCE_LIST_ID,
  videoSentLabelId: VIDEO_SENT_LABEL_ID,
  triggerLabelId: triggerLabel.id,
  triggerLabelName: triggerLabel.name,
  regenerateOnly,
  deliveryMode: regenerateOnly ? 'regenerate_only' : 'send_preview_email',
  videoProvider: 'grok',
  leaseAcquiredAt: now.toISOString(),
  leaseUntil: leaseUntil.toISOString()
} }];

const config = $('Config').first().json || {};
const rows = $input.all().map(i => i.json).filter(Boolean);
const row = Array.isArray(rows[0]) ? rows[0][0] : rows[0];
const extracted = $('Extract Preview Request ID').first().json || {};

if (extracted.requestIdConflict) {
  return [{ json: {
    cardId: config.cardId,
    cardName: config.cardName,
    requestId: '',
    requestUuid: '',
    customerId: '',
    acDealId: '',
    canonicalTrelloCardId: '',
    previewRequestOk: false,
    previewRequestError: extracted.requestIdConflictError || 'Conflicting Trello Request-IDs on card ' + (config.cardId || '-')
  } }];
}

if (!row || !row.request_id || !row.customer_id) {
  return [{ json: {
    cardId: config.cardId,
    cardName: config.cardName,
    requestId: $('Extract Preview Request ID').first().json.requestId || '',
    requestUuid: '',
    customerId: '',
    acDealId: '',
    canonicalTrelloCardId: '',
    previewRequestOk: false,
    previewRequestError: 'No request/customer match in master_requests for Trello card ' + (config.cardId || '-')
  } }];
}

return [{ json: {
  cardId: config.cardId,
  cardName: config.cardName,
  requestId: row.request_id,
  requestUuid: row.id,
  customerId: row.customer_id,
  acDealId: row.ac_deal_id || '',
  canonicalTrelloCardId: row.trello_card_id || '',
  canonicalTrelloCardUrl: row.trello_card_url || '',
  finalValue: row.final_value || null,
  previewRequestOk: true,
  previewRequestError: ''
} }];

const rows = $input.all().map(i => i.json).filter(Boolean);
const customer = Array.isArray(rows[0]) ? rows[0][0] : rows[0];
const prev = $('Validate Preview Request').first().json;

const emailRaw = String(customer && customer.email || '').trim();
const email = emailRaw.toLowerCase();
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const phone = String(customer && customer.phone || '').trim();

if (!emailValid && !phone) {
  throw new Error('Preview customer contact channel missing for request ' + prev.requestId + ': no valid email and no phone');
}

const roleAccount = false;

return [{ json: {
  ...prev,
  email: emailValid ? email : '',
  emailValid,
  emailMissing: !emailValid,
  skipCustomerEmail: !emailValid,
  whatsappFallbackOnly: !emailValid && !!phone,
  firstName: customer.first_name || '',
  lastName: customer.last_name || '',
  phone,
  country: customer.country || '',
  roleAccount
} }];

const rows = $input.all().map(i => i.json).filter(Boolean);
const quote = Array.isArray(rows[0]) ? rows[0][0] : rows[0];
const prev = $('Validate Preview Customer').first().json;

function isStablePandaDocLink(value) {
  const link = String(value || '').trim();
  return /^https:\/\/app\.pandadoc\.com\/document\//i.test(link) && !/\/s\//.test(link) && /(?:\?|&)token=/.test(link);
}

let previewQuoteOk = true;
let previewQuoteMissing = false;
let previewQuoteError = '';
const shareLink = String(quote?.share_link || '').trim();
const status = String(quote?.pandadoc_status || '').trim();

if (!quote || quote.error || quote.code === 'PGRST116' || !shareLink) {
  previewQuoteOk = false;
  previewQuoteMissing = true;
  const apiReason = quote?.error?.description || quote?.description || quote?.message || '';
  previewQuoteError = 'No stable PandaDoc share_link found in master_quotes for request ' + prev.requestId + (apiReason ? ' (' + apiReason + ')' : '');
} else if (!isStablePandaDocLink(shareLink)) {
  previewQuoteOk = false;
  previewQuoteError = 'PandaDoc link in master_quotes is not a stable customer document link for request ' + prev.requestId;
} else if (/completed|declined|expired/i.test(status)) {
  previewQuoteOk = false;
  previewQuoteError = 'Quote status blocks preview delivery: ' + status;
}

return [{ json: {
  ...prev,
  pandaDocId: quote?.pandadoc_id || '',
  pandaDocStatus: status,
  shareLink,
  previewQuoteOk,
  previewQuoteMissing,
  previewQuoteError,
  previewQuoteSource: previewQuoteOk ? 'master_quotes' : '',
  previewQuoteEvidence: previewQuoteOk ? { source: 'master_quotes', pandadoc_id: quote?.pandadoc_id || '' } : {}
} }];

function resolvedPreviewQuote() {
  try {
    const resolved = $('Validate Preview Quote after Resolver').first().json;
    if (resolved && resolved.previewQuoteOk === true && resolved.shareLink) return resolved;
  } catch (error) {}
  return $('Validate Preview Quote').first().json;
}
const prev = resolvedPreviewQuote();
const offerUrl = String(prev.shareLink || '').trim();

if (!offerUrl || /\/s\//.test(offerUrl)) {
  throw new Error('Refusing to send temporary or missing PandaDoc customer link for request ' + prev.requestId);
}

const enc = encodeURIComponent;
const customerName = [prev.firstName, prev.lastName].filter(Boolean).join(' ').trim() || prev.firstName || 'Kunde';
const cardId = prev.cardId;
const trelloUpload = $('Upload Video to Trello').first().json || {};
let supabaseUploadResult = {};
try {
  supabaseUploadResult = $('Upload Video to Supabase Storage').first().json || {};
} catch (error) {
  supabaseUploadResult = {};
}
const runwayVideoUrl = ($('Download Video').first().json || {}).videoUrl || '';
const supabaseUploadError = supabaseUploadResult.error || null;
const supabaseUploadOk = !supabaseUploadError;
const supabaseVideoUrl = 'https://klibiejfisijpagzkxls.supabase.co/storage/v1/object/public/product-images/preview-videos/' + enc(prev.requestId) + '/Mockup01_video.mp4';

if (!trelloUpload.id || !trelloUpload.fileName) {
  throw new Error('Trello video upload missing attachment id/fileName for card ' + cardId);
}

const proxyBase = 'https://video.neontrip.de/media/video';
const trelloProxyVideoUrl = proxyBase + '?' + [
  'cardId=' + enc(cardId),
  'attachmentId=' + enc(trelloUpload.id),
  'fileName=' + enc(trelloUpload.fileName)
].join('&');
const videoUrl = supabaseUploadOk ? supabaseVideoUrl : trelloProxyVideoUrl;

const selectedMockup = $('Find Mockup').first().json || {};
if (!selectedMockup.selectedMockupAttachmentId || !selectedMockup.selectedMockupFileName) {
  throw new Error('Refusing preview delivery without customer-safe selected mockup for card ' + cardId);
}
const thumbUrl = 'https://video.neontrip.de/media/image?' + [
  'cardId=' + enc(cardId),
  'attachmentId=' + enc(selectedMockup.selectedMockupAttachmentId),
  'fileName=' + enc(selectedMockup.selectedMockupFileName)
].join('&');
function qs(params) {
  return Object.entries(params)
    .map(([key, value]) => enc(key) + '=' + enc(String(value || '')))
    .join('&');
}

const rawProjectName = String(prev.cardName || '').trim();
const projectName = rawProjectName
  .replace(/^FEHLER\s*[-:]\s*/i, '')
  .trim() || 'NEONTRIP Angebot';
const videoHostingStatus = supabaseUploadOk ? 'supabase_storage' : 'supabase_failed_trello_proxy';
const regenerateOnly = $('Config').first().json.regenerateOnly === true;
const customerEmail = String(prev.email || '').trim().toLowerCase();
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customerEmail);
const phonePresent = String(prev.phone || '').trim().length > 5;
const whatsappFallbackOnly = !emailValid && phonePresent && !regenerateOnly;
const skipCustomerEmail = regenerateOnly || whatsappFallbackOnly || prev.skipCustomerEmail === true;

const previewUrl = 'https://video.neontrip.de/v/demo/?' + qs({
  name: customerName,
  offer: offerUrl,
  video: videoUrl,
  thumb: thumbUrl,
  project: projectName
});

return [{ json: {
  customer_name: customerName,
  customer_email: emailValid ? customerEmail : '',
  customer_phone: prev.phone || '',
  customer_country: prev.country || '',
  role_account: prev.roleAccount === true,
  request_id: prev.requestId,
  card_id: cardId,
  project_name: projectName,
  pandadoc_customer_link: offerUrl,
  pandadoc_document_link: prev.shareLink || '',
  whatsapp_pandadoc_link: prev.shareLink || offerUrl,
  preview_url: previewUrl,
  video_url: videoUrl,
  thumb_url: thumbUrl,
  s3_upload_error: null,
  supabase_upload_error: supabaseUploadError,
  supabase_video_url: supabaseVideoUrl,
  runway_video_url: runwayVideoUrl,
  trello_video_attachment_id: trelloUpload.id,
  video_url_is_temporary: false,
  video_hosting_status: videoHostingStatus,
  regenerate_only: regenerateOnly,
  skip_customer_email: skipCustomerEmail,
  whatsapp_fallback_only: whatsappFallbackOnly,
  email_missing: !emailValid,
  delivery_mode: regenerateOnly ? 'regenerate_only' : (whatsappFallbackOnly ? 'whatsapp_fallback_only' : 'send_preview_email'),
  source: 'ki_video_generator_v1'
} }];

const config = $('Config').first().json;
const card = $input.first().json || {};
const customFieldItems = Array.isArray(card.customFieldItems) ? card.customFieldItems : [];
const NERDY_FORMS_FIELD_ID = '67a200bd23b1ffd304e63335';

const field = customFieldItems.find((item) => item.idCustomField === NERDY_FORMS_FIELD_ID);
const value = field && field.value ? field.value : {};
const customRequestId = String(value.text || value.number || value.date || '').trim();

const desc = String(card.desc || '');
const descMatch = desc.match(/(?:request[_ -]?id|nerdyforms?[_ -]?id|anfrage[_ -]?id)\s*[:#-]?\s*([a-zA-Z0-9_-]+)/i);
const descRequestId = descMatch ? String(descMatch[1]).trim() : '';
const requestIdConflict = Boolean(customRequestId && descRequestId && customRequestId !== descRequestId);
const requestId = requestIdConflict ? '' : (customRequestId || descRequestId);
const requestIdSource = requestIdConflict ? 'conflict' : (customRequestId ? 'trello_custom_field' : (descRequestId ? 'trello_description' : 'none'));
const requestIdConflictError = requestIdConflict
  ? `Conflicting Trello Request-IDs: custom_field=${customRequestId}, description=${descRequestId}`
  : '';

return [{ json: {
  ...config,
  requestId,
  requestIdSource,
  customRequestId,
  descRequestId,
  requestIdConflict,
  requestIdConflictError
} }];

