const payload = $('Build Preview Delivery Payload').first().json || {};
const delivery = $('Send Preview Delivery').first().json || {};

return [{ json: {
  ...payload,
  delivery_ok: delivery.ok === true,
  sent_customer_email: delivery.sent_customer_email === true,
  sent_test_email: delivery.sent_test_email === true,
  skipped_customer_email: delivery.skipped_customer_email === true,
  subject: delivery.subject || 'Ihr NEONTRIP-Angebot mit Vorschau'
} }];

const data = $input.first().json || {};
const rawPhone = String(data.customer_phone || data.phone || '').trim();
const country = String(data.customer_country || data.country || 'DE').trim().toLowerCase();
const deliveryMode = String(data.delivery_mode || '').trim();

const countryCodeMap = {
  deutschland: '+49', germany: '+49', de: '+49',
  oesterreich: '+43', österreich: '+43', austria: '+43', at: '+43',
  schweiz: '+41', switzerland: '+41', ch: '+41'
};

function normalizePhone(raw, countryName) {
  if (!raw) return '';
  let cleaned = raw.replace(/[^0-9+]/g, '');
  if (cleaned.startsWith('+')) return cleaned;
  if (cleaned.startsWith('00')) return '+' + cleaned.substring(2);
  const countryCode = countryCodeMap[countryName] || '+49';
  if (cleaned.startsWith('0')) return countryCode + cleaned.substring(1);
  return countryCode + cleaned;
}

const normalizedPhone = normalizePhone(rawPhone, country);
const whatsappPandaDocLink = String(data.whatsapp_pandadoc_link || data.pandadoc_document_link || data.pandadoc_customer_link || '').trim();
const urlParts = whatsappPandaDocLink.split('/document/');
const pandaDocToken = urlParts.length > 1 ? urlParts[1] : '';
const firstName = String(data.first_name || data.customer_first_name || data.customer_name || 'Kunde').trim().split(/\s+/)[0] || 'Kunde';
const hasPhone = normalizedPhone.length > 5;
const hasTemplateLink = pandaDocToken.length > 5;
const canAttemptWhatsapp = data.regenerate_only !== true && (
  data.sent_customer_email === true ||
  data.skipped_customer_email === true ||
  data.whatsapp_fallback_only === true ||
  deliveryMode === 'whatsapp_fallback_only'
);

let whatsappSkipReason = '';
if (data.regenerate_only === true) whatsappSkipReason = 'regenerate_only';
else if (!canAttemptWhatsapp) whatsappSkipReason = 'whatsapp_not_enabled_for_delivery_mode';
else if (!hasPhone) whatsappSkipReason = 'missing_phone';
else if (!hasTemplateLink) whatsappSkipReason = 'missing_pandadoc_document_link';

return [{ json: {
  ...data,
  normalizedPhone,
  firstName,
  whatsappPandaDocLink,
  pandaDocToken,
  hasPhone,
  hasTemplateLink,
  whatsappReady: canAttemptWhatsapp && hasPhone && hasTemplateLink,
  whatsappSkipReason
} }];

