const requestId = $('Extract Preview Request ID').first().json.requestId || '';
const baseUrl = 'https://klibiejfisijpagzkxls.supabase.co/storage/v1/object/public/pandadoc-mockups';
const mockup01Url = baseUrl + '/' + requestId + '/Mockup01.jpg';
const mockup02Url = baseUrl + '/' + requestId + '/Mockup02.jpg';
const fallbackUrl = baseUrl + '/_fallback/default.png';

const httpFn = (this.helpers && this.helpers.httpRequest) ? this.helpers.httpRequest.bind(this.helpers)
             : (typeof $helpers !== 'undefined' && $helpers.httpRequest) ? $helpers.httpRequest
             : null;

async function urlExists(url) {
  if (!httpFn) {
    return { ok: false, status: 0, error: 'httpRequest helper not available' };
  }
  try {
    const res = await httpFn({
      method: 'GET',
      url: url,
      headers: { 'Range': 'bytes=0-0' },
      returnFullResponse: true,
      timeout: 8000
    });
    return { ok: res.statusCode === 200 || res.statusCode === 206, status: res.statusCode };
  } catch (e) {
    return { ok: false, status: -1, error: String(e.message || e).slice(0, 200) };
  }
}

const test01 = requestId ? await urlExists(mockup01Url) : { ok: false, status: 0, error: 'no requestId' };
const test02 = (requestId && !test01.ok) ? await urlExists(mockup02Url) : { ok: false, status: 0, error: test01.ok ? 'skipped' : 'no requestId' };

let headerImageUrl;
let chosenSource;

if (test01.ok) {
  headerImageUrl = mockup01Url;
  chosenSource = 'mockup01';
} else if (test02.ok) {
  headerImageUrl = mockup02Url;
  chosenSource = 'mockup02';
} else {
  headerImageUrl = fallbackUrl;
  chosenSource = 'fallback';
}

return [{ json: {
  headerImageUrl,
  chosenSource,
  requestId,
  mockup01Url,
  mockup02Url,
  fallbackUrl,
  debug: {
    httpFnAvailable: !!httpFn,
    test01,
    test02
  }
} }];

