  releasedCardId: config.cardId,
  previousLeaseCardId: currentLeaseCardId || null,
  releasedAt: new Date().toISOString()
} }];

const prev = $('Validate Preview Quote').first().json;
const body = $input.first().json || {};
const docs = Array.isArray(body.results) ? body.results : (Array.isArray(body.documents) ? body.documents : (Array.isArray(body) ? body : []));
const requestId = String(prev.requestId || '').trim();
const blockedStatus = /completed|declined|expired/i;

const candidates = docs
  .filter(doc => doc && doc.id)
  .filter(doc => !blockedStatus.test(String(doc.status || '')))
  .filter(doc => String(doc.name || doc.title || '').includes(requestId));

if (!requestId || candidates.length === 0) {
  return [{ json: {
    ...prev,
    previewQuoteOk: false,
    previewQuoteMissing: false,
    previewResolverDocumentFound: false,
    previewQuoteError: 'No verified PandaDoc document found by request_id after missing master_quotes link for request ' + (requestId || '-'),
    previewQuoteEvidence: {
      source: 'pandadoc_search',
      searched_request_id: requestId,
      returned_count: docs.length
    }
  } }];
}

const doc = candidates
  .sort((a, b) => String(b.date_modified || b.updated_at || '').localeCompare(String(a.date_modified || a.updated_at || '')))[0];

return [{ json: {
  ...prev,
  previewResolverDocumentFound: true,
  pandaDocId: doc.id,
  pandaDocStatus: String(doc.status || '').replace(/^document\./, ''),
  previewQuoteEvidence: {
    source: 'pandadoc_search',
    searched_request_id: requestId,
    returned_count: docs.length,
    selected_document_id: doc.id,
    selected_document_name: doc.name || doc.title || '',
    selected_document_status: doc.status || ''
  }
} }];

const prev = $('Select Preview PandaDoc Document').first().json;
const details = $input.first().json || {};
const requestId = String(prev.requestId || '').trim();
const expectedEmail = String(prev.email || '').trim().toLowerCase();
const recipients = Array.isArray(details.recipients) ? details.recipients : [];
const matchingRecipient = recipients.find(r => String(r.email || '').trim().toLowerCase() === expectedEmail);
const recipientWithLink = matchingRecipient || recipients.find(r => r && r.shared_link);
const shareLink = String(recipientWithLink?.shared_link || details.shared_link || '').trim();
const status = String(details.status || prev.pandaDocStatus || '').replace(/^document\./, '');
const documentName = String(details.name || prev.previewQuoteEvidence?.selected_document_name || '');
const hasRequestEvidence = documentName.includes(requestId);
const recipientEmails = recipients.map(r => String(r.email || '').trim().toLowerCase()).filter(Boolean);
const recipientMatchesCustomer = !recipientEmails.length || recipientEmails.includes(expectedEmail);
const totalValue = (details.grand_total || {}).amount || (details.pricing || {}).total || prev.finalValue || null;

function stableLink(value) {
  const link = String(value || '').trim();
  return /^https:\/\/app\.pandadoc\.com\/document\//i.test(link) &&
    !/\/s\//.test(link) &&
    /(?:\?|&)token=/.test(link);
}

let resolverQuoteOk = true;
let previewQuoteError = '';

if (!hasRequestEvidence) {
  resolverQuoteOk = false;
  previewQuoteError = 'PandaDoc document details did not prove request_id ownership for request ' + requestId;
} else if (!recipientMatchesCustomer) {
  resolverQuoteOk = false;
  previewQuoteError = 'PandaDoc recipient email does not match master_customers email for request ' + requestId;
} else if (!stableLink(shareLink)) {
  resolverQuoteOk = false;
  previewQuoteError = 'PandaDoc details did not provide a stable customer share_link for request ' + requestId;
} else if (/completed|declined|expired/i.test(status)) {
  resolverQuoteOk = false;
  previewQuoteError = 'PandaDoc status blocks preview delivery: ' + status;
}

return [{ json: {
  ...prev,
  pandaDocId: String(details.id || prev.pandaDocId || '').trim(),
  pandaDocStatus: status,
  shareLink,
  resolverQuoteOk,
  previewQuoteOk: resolverQuoteOk,
  previewQuoteMissing: false,
  previewQuoteError,
  previewQuoteSource: resolverQuoteOk ? 'pandadoc_api_backfill' : '',
  previewQuoteEvidence: {
    ...(prev.previewQuoteEvidence || {}),
    source: 'pandadoc_api_backfill',
    details_document_id: details.id || prev.pandaDocId || '',
    details_document_name: documentName,
    recipient_email_match: recipientMatchesCustomer,
    request_id_in_document_name: hasRequestEvidence
  },
  masterQuoteUpsert: resolverQuoteOk ? {
    pandadoc_id: String(details.id || prev.pandaDocId || '').trim(),
    request_id: requestId,
    customer_id: prev.customerId,
    pandadoc_status: status || 'sent',
    share_link: shareLink,
    edit_link: 'https://app.pandadoc.com/a/#/documents/' + String(details.id || prev.pandaDocId || '').trim(),
    total_value: totalValue,
    updated_at: new Date().toISOString()
  } : null
} }];

const rows = $input.all().map(i => i.json).filter(Boolean);
const quote = Array.isArray(rows[0]) ? rows[0][0] : rows[0];
const prev = $('Prepare Preview Quote Upsert').first().json;
const shareLink = String(quote?.share_link || prev.shareLink || '').trim();
const status = String(quote?.pandadoc_status || prev.pandaDocStatus || '').trim();
const pandaDocId = String(quote?.pandadoc_id || prev.pandaDocId || '').trim();

function stableLink(value) {
  const link = String(value || '').trim();
  return /^https:\/\/app\.pandadoc\.com\/document\//i.test(link) && !/\/s\//.test(link) && /(?:\?|&)token=/.test(link);
}

let previewQuoteOk = true;
let previewQuoteError = '';

if (!pandaDocId || !stableLink(shareLink)) {
  previewQuoteOk = false;
  previewQuoteError = 'Resolved PandaDoc quote was not persisted as a stable master_quotes row for request ' + prev.requestId;
} else if (/completed|declined|expired/i.test(status)) {
  previewQuoteOk = false;
  previewQuoteError = 'Quote status blocks preview delivery after resolver: ' + status;
}

return [{ json: {
  ...prev,
  pandaDocId,
  pandaDocStatus: status,
  shareLink,
  previewQuoteOk,
  previewQuoteMissing: false,
  previewQuoteError,
  previewQuoteSource: previewQuoteOk ? 'master_quotes_after_pandadoc_resolver' : '',
  previewQuoteEvidence: {
    ...(prev.previewQuoteEvidence || {}),
    source: 'master_quotes_after_pandadoc_resolver',
    persisted_pandadoc_id: pandaDocId
  }
} }];
